// testFailure is the locale key of a failed test outcome.
func testFailure(status string) string {
	switch status {
	case "no_address":
		return "NoAddress"
	case "gone":
		return "Gone"
	case "disabled":
		return "Disabled"
	case "unavailable":
		return "Unavailable"
	}
	return "Unknown"
}

